window.__GUIDE_CHUNKS__.push([{"id": "28-002", "chapter_num": 28, "chapter_title": "Don't wreck your health for looks", "chapter_file": "28-health-vs-looks.md", "number": 2, "title": "Check who is allowed to inject before you sit in the chair", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free to check. It costs walking away from a cheap deal.", "plain": "In Ontario, injections that pierce the skin with drugs — Botox, fillers — are controlled acts under the health law: only authorized professionals — including people working under their delegation — may perform them. A med spa's Instagram following is not a credential. Ask who the medical director is and who actually holds the needle.", "benefit_text": "Ontario's Regulated Health Professions Act, s.27: administering a substance by injection is a controlled act; the College of Physicians and Surgeons of Ontario requires proper delegation and supervision. Unregulated injectors have caused infections, vascular injuries, and blindness.", "sources": "Regulated Health Professions Act, 1991, S.O. 1991, c. 18, s.27 (current consolidation) — https://www.ontario.ca/laws/statute/91r18", "notes": "", "urls": ["https://www.ontario.ca/laws/statute/91r18"]}, {"id": "28-003", "chapter_num": 28, "chapter_title": "Don't wreck your health for looks", "chapter_file": "28-health-vs-looks.md", "number": 3, "title": "Know where fillers blind people", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free to know. It costs choosing a trained injector over a cheap one.", "plain": "Filler injected into a blood vessel can travel to the eye and blind it within minutes. A 2024 update counted the danger zones: the nose first, then the forehead, then the glabella between the brows. Hyaluronic-acid fillers caused most cases — which matters, because they are the one type an antidote enzyme can dissolve.", "benefit_text": "A 2024 systematic update (PMID 38630871): among reported filler-related blindness cases, injection sites were the nose 40.6%, forehead 27.7%, and glabella 19.0%; hyaluronic acid fillers accounted for 79.6% of cases. The enzyme hyaluronidase can dissolve HA filler in an emergency — one reason clinicians prefer it.", "sources": "https://pubmed.ncbi.nlm.nih.gov/38630871/", "notes": "", "urls": ["https://pubmed.ncbi.nlm.nih.gov/38630871/"]}, {"id": "28-004", "chapter_num": 28, "chapter_title": "Don't wreck your health for looks", "chapter_file": "28-health-vs-looks.md", "number": 4, "title": "Do not swallow \"fast slimming\" pills from unofficial channels", "money": "low", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "The pills themselves are cheap; the price is your heart.", "plain": "The famous banned diet drug sibutramine raised heart-attack and stroke risk enough to be pulled from the market — and it keeps turning up in illegal \"herbal\" slimming products. Anything that promises fast weight loss without a prescription deserves the assumption that it contains something banned.", "benefit_text": "The SCOUT trial (NEJM 2010): sibutramine raised the risk of the primary cardiovascular outcome (HR 1.16), nonfatal heart attack (HR 1.28), and nonfatal stroke (HR 1.36) in overweight and obese subjects. Health Canada had the drug withdrawn from the Canadian market in October 2010, and it still appears as an undeclared ingredient in seized \"natural\" weight-loss products.", "sources": "https://www.nejm.org/doi/full/10.1056/nejmoa1003114?cookieSet=1 and https://www.news-medical.net/news/20101011/Abbott-to-withdraw-sibutramine-from-Canadian-market.aspx", "notes": "", "urls": ["https://www.nejm.org/doi/full/10.1056/nejmoa1003114?cookieSet=1", "https://www.news-medical.net/news/20101011/Abbott-to-withdraw-sibutramine-from-Canadian-market.aspx"]}, {"id": "28-005", "chapter_num": 28, "chapter_title": "Don't wreck your health for looks", "chapter_file": "28-health-vs-looks.md", "number": 5, "title": "Do not take steroids for the mirror", "money": "low", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "The drugs cost money; the side effects cost health.", "plain": "Anabolic steroids build muscle at the price of the heart, the liver, fertility, and mood. A long-term follow-up of men sanctioned for steroid use found triple the death rate of matched controls. The physique fades when the drugs stop; the heart damage does not have to.", "benefit_text": "Horwitz et al., 2019: 545 Danish men sanctioned for androgen use versus 5,450 controls; all-cause mortality HR 3.0 over the follow-up. Documented harms include heart failure, liver tumours, infertility, and aggression.", "sources": "https://onlinelibrary.wiley.com/doi/10.1111/joim.12850", "notes": "", "urls": ["https://onlinelibrary.wiley.com/doi/10.1111/joim.12850"]}, {"id": "28-006", "chapter_num": 28, "chapter_title": "Don't wreck your health for looks", "chapter_file": "28-health-vs-looks.md", "number": 6, "title": "Get weight-loss drugs only by real prescription, from a real pharmacy", "money": "high", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "death", "evidence": "C", "grade": "C", "disputed": false, "cost": "Hundreds of dollars a month without coverage; the medical supervision is the point.", "plain": "GLP-1 drugs work, but they are not candy: they need dose titration, monitoring for gallbladder and pancreas problems, and a plan for keeping the weight off after stopping. Buying them from a website, a friend's leftover pen, skips every safety layer at once.", "benefit_text": "Health Canada public advisory: do not buy or use unauthorized or counterfeit GLP-1 drugs (semaglutide, tirzepatide); unauthorized products may contain too much, too little, or none of the active ingredient, plus unlisted dangerous ingredients or contaminants — and they have not been assessed for safety, effectiveness, or quality. Only buy prescription drugs from licensed pharmacies.", "sources": "Health Canada — public advisory on unauthorized and counterfeit GLP-1 drugs (Jan 2026), listed in Health Product InfoWatch, Feb 2026. <https://publications.gc.ca/collections/collection_2026/sc-hc/H167-1-2026-2-eng.pdf>", "notes": "", "urls": ["https://publications.gc.ca/collections/collection_2026/sc-hc/H167-1-2026-2-eng.pdf"]}, {"id": "28-007", "chapter_num": 28, "chapter_title": "Don't wreck your health for looks", "chapter_file": "28-health-vs-looks.md", "number": 7, "title": "Take sex hormones only with a doctor watching", "money": "low", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "The prescription and the blood tests; the monitoring is the point.", "plain": "Testosterone for men who do not need it and estrogen for goals a doctor has not evaluated both carry clot and heart risks that rise with years of use. Hormones reshape the body slowly and the risks accumulate silently — this is specialist territory, not internet-forum territory.", "benefit_text": "Getahun et al., 2018: estrogen therapy was associated with higher venous thromboembolism risk — 4.1 more cases per 1,000 at 2 years and 16.7 more per 1,000 at 8 years versus cisgender men; exogenous testosterone raises hematocrit and blood pressure. PMC6636681.", "sources": "https://pmc.ncbi.nlm.nih.gov/articles/PMC6636681/", "notes": "", "urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC6636681/"]}, {"id": "28-008", "chapter_num": 28, "chapter_title": "Don't wreck your health for looks", "chapter_file": "28-health-vs-looks.md", "number": 8, "title": "Get screened for body dysmorphia before cosmetic surgery", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free — a short questionnaire. It costs facing an answer you may not want.", "plain": "When the mirror shows a flaw no one else can see, surgery on the flaw rarely fixes the distress — the distress moves to a new spot. A short screening questionnaire before any cosmetic procedure catches body dysmorphic disorder, which responds to therapy, not to the scalpel.", "benefit_text": "A JAMA Facial Plastic Surgery study of 597 patients at 3 clinics: 58 patients (9.7%) screened positive for BDD on the validated BDDQ questionnaire — 13.1% of cosmetic-surgery seekers — while surgeons correctly identified only 2 of 43 (4.7%). The authors recommend routine use of validated screening instruments before surgery. PMC5543317.", "sources": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5543317/", "notes": "", "urls": ["https://pmc.ncbi.nlm.nih.gov/articles/PMC5543317/"]}, {"id": "29-001", "chapter_num": 29, "chapter_title": "After a hard blow", "chapter_file": "29-after-a-hard-blow.md", "number": 1, "title": "After a death in the family, treat chest pain as a 911 call", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "C", "grade": "C", "disputed": false, "cost": "No money; calling emergency services instead of waiting it out.", "plain": "The risk of a heart attack spikes in the first day after losing someone close, and stroke risk stays raised for weeks. Do not drive yourself to the hospital.", "benefit_text": "Heart-attack risk runs about twenty-one times normal in the first twenty-four hours of bereavement; stroke risk more than doubles in the month after — figures UNVERIFIED in this edition (ported from the Mostofsky/Carey studies named in Notes; not verified against the studies). Fast emergency care makes the difference.", "sources": "211 — community and social supports directory (cited for the support resource, not the risk figures). https://211.ca/", "notes": "UNVERIFIED — risk figures ported from peer-reviewed studies (Mostofsky on MI timing; Carey on stroke after bereavement) without verified citations; the cited 211 page states none of them. 211 connects to non-emergency community supports; call 911 for chest pain. See docs/verification/spot-read.md.", "urls": ["https://211.ca/"]}, {"id": "29-002", "chapter_num": 29, "chapter_title": "After a hard blow", "chapter_file": "29-after-a-hard-blow.md", "number": 2, "title": "Save 988 in every family phone now", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; one minute to save the number.", "plain": "Call and text, any time, day and night, from anywhere in Canada. The line works in English and French only — when the person in crisis speaks neither, arrange a bilingual helper to sit with them.", "benefit_text": "The national suicide crisis line launched November 30, 2023; free, confidential, reachable by call and text around the clock.", "sources": "https://www.canada.ca/en/public-health/news/2023/11/9-8-8-suicide-crisis-helpline.html", "notes": "Trap for Chinese-speaking families: 988 itself offers no Mandarin or Cantonese service.", "urls": ["https://www.canada.ca/en/public-health/news/2023/11/9-8-8-suicide-crisis-helpline.html"]}, {"id": "29-003", "chapter_num": 29, "chapter_title": "After a hard blow", "chapter_file": "29-after-a-hard-blow.md", "number": 3, "title": "Guard the first week after a cancer diagnosis", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "death", "evidence": "C", "grade": "C", "disputed": false, "cost": "No money; staying close and watching for warning signs.", "plain": "Suicide and fatal heart events cluster in the days right after the diagnosis lands. Company, sleep, and a follow-up appointment that week matter more than optimism.", "benefit_text": "Suicide risk runs about twelve times normal and fatal cardiovascular events about five to six times normal in the first week after diagnosis — figures UNVERIFIED in this edition (ported from a Fang et al. registry study; not verified against the study).", "sources": "9-8-8 Suicide Crisis Helpline (cited for the crisis resource, not the risk figures). https://www.canada.ca/en/public-health/news/2023/11/9-8-8-suicide-crisis-helpline.html", "notes": "UNVERIFIED — risk figures ported from a peer-reviewed registry study (Fang et al.) without a verified citation; the cited helpline page states none of them. The 988 line is the Canadian crisis resource for the suicide component. See docs/verification/spot-read.md.", "urls": ["https://www.canada.ca/en/public-health/news/2023/11/9-8-8-suicide-crisis-helpline.html"]}, {"id": "29-004", "chapter_num": 29, "chapter_title": "After a hard blow", "chapter_file": "29-after-a-hard-blow.md", "number": 4, "title": "After a suicide loss, protect the survivors — starting with yourself", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; reaching out instead of withdrawing.", "plain": "Losing someone to suicide raises the survivors' own risk. Contact with a crisis line and counsellor in the first months lowers it — do not grieve alone.", "benefit_text": "Suicide bereavement raises survivors' own suicide risk; early contact with crisis support lowers it.", "sources": "https://www.canada.ca/en/public-health/news/2023/11/9-8-8-suicide-crisis-helpline.html", "notes": "Evidence note: risk figures ported from registry studies (Erlangsen).", "urls": ["https://www.canada.ca/en/public-health/news/2023/11/9-8-8-suicide-crisis-helpline.html"]}, {"id": "29-005", "chapter_num": 29, "chapter_title": "After a hard blow", "chapter_file": "29-after-a-hard-blow.md", "number": 5, "title": "Widowhood raises mortality — schedule support and checkups", "money": "0", "time": "low", "willpower": "some", "benefit": "mid", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; the effort to accept help and book appointments.", "plain": "The months after losing a spouse carry the highest risk. Line up company, keep medical appointments, and let people help with daily life.", "benefit_text": "Mortality runs about forty percent above normal in the first six months after losing a spouse.", "sources": "https://211.ca/", "notes": "Evidence note: risk figure ported from a peer-reviewed meta-analysis (Moon et al.). 211 connects to bereavement and community supports.", "urls": ["https://211.ca/"]}, {"id": "29-006", "chapter_num": 29, "chapter_title": "After a hard blow", "chapter_file": "29-after-a-hard-blow.md", "number": 6, "title": "When grief does not lift after months, see a family doctor", "money": "0", "time": "low", "willpower": "some", "benefit": "low", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money with provincial health coverage; one appointment.", "plain": "Grief that stays intense and disabling for many months is a treatable condition, not a character flaw. A family doctor can assess it and refer to targeted therapy.", "benefit_text": "About one in ten bereaved people develops prolonged grief; targeted therapy roughly doubles recovery compared with standard talk therapy.", "sources": "https://www.canada.ca/en/public-health/news/2023/11/9-8-8-suicide-crisis-helpline.html", "notes": "Evidence note: figures ported from clinical trials (Shear).", "urls": ["https://www.canada.ca/en/public-health/news/2023/11/9-8-8-suicide-crisis-helpline.html"]}, {"id": "29-007", "chapter_num": 29, "chapter_title": "After a hard blow", "chapter_file": "29-after-a-hard-blow.md", "number": 7, "title": "When you lose your job, file for EI at once", "money": "0", "time": "mid", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; the application and the wait for the first payment.", "plain": "File the day work ends — late claims can cost you weeks of benefits. While the claim runs, treat the search for the next job as the job.", "benefit_text": "EI pays fifty-five percent of insurable earnings up to $729 per week in 2026; unemployment is linked with about sixty percent higher mortality, so income protection is health protection.", "sources": "https://www.canada.ca/en/services/benefits/ei/ei-regular-benefit/benefit-amount.html", "notes": "Evidence note: mortality link ported from a peer-reviewed meta-analysis (Roelfs); EI figures are federal. Quebec note: EI regular benefits apply in Quebec — only parental benefits differ under QPIP.", "urls": ["https://www.canada.ca/en/services/benefits/ei/ei-regular-benefit/benefit-amount.html"]}, {"id": "29-008", "chapter_num": 29, "chapter_title": "After a hard blow", "chapter_file": "29-after-a-hard-blow.md", "number": 8, "title": "Delay irreversible money decisions for three months", "money": "0", "time": "low", "willpower": "yes", "benefit": "mid", "dimension": "money", "evidence": "C", "grade": "C", "disputed": false, "cost": "No money; the discipline to wait.", "plain": "Grief wrecks financial judgment for months. Put selling the house, quitting the job, and large gifts behind a waiting rule — reversible choices now, big ones later.", "benefit_text": "A three-month rule prevents grief-driven sales, resignations, and gifts that cannot be undone.", "sources": "https://www.canada.ca/en/national-seniors-council/programs/publications-reports/2019-what-we-heard-financial-crimes-harms.html", "notes": "The cited source addresses financial vulnerability in seniors; applied here to grief-impaired judgment generally.", "urls": ["https://www.canada.ca/en/national-seniors-council/programs/publications-reports/2019-what-we-heard-financial-crimes-harms.html"]}, {"id": "29-009", "chapter_num": 29, "chapter_title": "After a hard blow", "chapter_file": "29-after-a-hard-blow.md", "number": 9, "title": "Divorce: know the one-year rule and keep coverage continuous", "money": "low", "time": "mid", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Low money for legal advice before signing anything; time to inventory joint accounts and policies.", "plain": "Canada grants divorce after breakdown shown by living apart for at least a year. Do not let drug and dental coverage lapse in the gap between separating and settling.", "benefit_text": "The Divorce Act requires at least one year of living separate and apart (section 8); keeping health coverage continuous avoids paying out of pocket during the split.", "sources": "https://laws-lois.justice.gc.ca/eng/acts/D-3.4/page-2.html?txthl=sections+section", "notes": "Evidence note: health effects of divorce ported from research (Sbarra); the statute is primary. Quebec note: property division follows the Civil Code (family patrimony), not Ontario equalization — get Quebec-specific advice.", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/D-3.4/page-2.html?txthl=sections+section"]}, {"id": "29-010", "chapter_num": 29, "chapter_title": "After a hard blow", "chapter_file": "29-after-a-hard-blow.md", "number": 10, "title": "After a suicide in the family, check the insurance clock and the survivor pension", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; reading the policy and one call to Service Canada.", "plain": "Many life-insurance policies exclude suicide in the first two years. Separately, the surviving spouse may qualify for a CPP survivor pension — money families often do not know exists.", "benefit_text": "CPP survivor pension: sixty percent of the contributor's pension from age sixty-five (under sixty-five, a flat rate plus thirty-seven and a half percent); the estate pays debts before heirs inherit.", "sources": "https://www.canada.ca/en/services/benefits/publicpensions/cpp/cpp-survivor-pension.html https://beta18.vortexsolution.com/laverysandbox/DATA/PUBLICATION/65_en~v~dealing-with-suicide-occurring-within-two-years-of-reinstatement-of-a-life-insurance-policy.pdf", "notes": "UNVERIFIED — the two-year suicide exclusion (art. 2441 C.C.Q.) rests on a 1999 legal commentary, not the current Civil Code text; confirm with the policy itself. See docs/verification/29-after-a-hard-blow.md.", "urls": ["https://beta18.vortexsolution.com/laverysandbox/DATA/PUBLICATION/65_en~v~dealing-with-suicide-occurring-within-two-years-of-reinstatement-of-a-life-insurance-policy.pdf", "https://www.canada.ca/en/services/benefits/publicpensions/cpp/cpp-survivor-pension.html"]}, {"id": "29-011", "chapter_num": 29, "chapter_title": "After a hard blow", "chapter_file": "29-after-a-hard-blow.md", "number": 11, "title": "Dial 211 when you do not know where to turn", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "time", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; the call is free and confidential.", "plain": "Food, shelter, counselling, legal aid — when the problem is \"I need help\" without a clear address, 211 navigators know the local map.", "benefit_text": "211 is Canada's primary referral line for community and social services: free, confidential, twenty-four hours a day, in more than one hundred fifty languages.", "sources": "https://211.ca/", "notes": "", "urls": ["https://211.ca/"]}, {"id": "29-012", "chapter_num": 29, "chapter_title": "After a hard blow", "chapter_file": "29-after-a-hard-blow.md", "number": 12, "title": "Tell children the truth about death, in words they can grasp", "money": "0", "time": "low", "willpower": "yes", "benefit": "low", "dimension": "time", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; the courage to be direct.", "plain": "Euphemisms confuse children more than honest words. Say the person died, explain what that means in simple terms, and let them ask questions.", "benefit_text": "Honest, age-appropriate explanations are linked with about half the later psychiatric risk of evasive ones.", "sources": "https://211.ca/", "notes": "Evidence note: figure ported from a longitudinal study (Li et al.). 211 connects to family and grief counselling services.", "urls": ["https://211.ca/"]}, {"id": "29-013", "chapter_num": 29, "chapter_title": "After a hard blow", "chapter_file": "29-after-a-hard-blow.md", "number": 13, "title": "Skip generic grief counselling for normal grief", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "time", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; the time you do not spend.", "plain": "Ordinary grief heals with time and company. Paid counselling for typical grief shows little effect — save professional help for grief that turns prolonged (item six).", "benefit_text": "For normal grief, generic counselling shows little to no benefit; skipping it saves money and evenings.", "sources": "https://211.ca/", "notes": "Evidence note: finding ported from a peer-reviewed meta-analysis (Currier).", "urls": ["https://211.ca/"]}, {"id": "30-001", "chapter_num": 30, "chapter_title": "School-age children", "chapter_file": "30-school-age-children.md", "number": 1, "title": "Treat sudden testicle pain in a boy as an emergency", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "C", "grade": "C", "disputed": false, "cost": "No money; a trip to the emergency department instead of waiting.", "plain": "Sudden severe pain with swelling can mean the cord twisted and cut off blood flow. Every hour counts — this is a call-an-ambulance situation, not a wait-and-see one.", "benefit_text": "Testicle salvage runs about ninety-seven percent when surgery happens within six hours, falling to about forty-two percent after nineteen to twenty-four hours — figures UNVERIFIED in this edition (ported from a Mellick study; not verified against the study).", "sources": "What OHIP covers (cited for emergency-care coverage, not the torsion figures). https://www.ontario.ca/page/what-ohip-covers", "notes": "UNVERIFIED — salvage figures ported from a peer-reviewed study (Mellick) without a verified citation; the cited OHIP page states none of them. Emergency care is covered under OHIP. See docs/verification/spot-read.md.", "urls": ["https://www.ontario.ca/page/what-ohip-covers"]}, {"id": "30-002", "chapter_num": 30, "chapter_title": "School-age children", "chapter_file": "30-school-age-children.md", "number": 2, "title": "Get two hours of outdoor time daily to slow myopia", "money": "0", "time": "mid", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "C", "grade": "C", "disputed": false, "cost": "No money; two hours of the day, every day.", "plain": "Bright outdoor light slows the eye growth that causes nearsightedness. Weekends do not make up for dark weekdays — the light needs to be daily.", "benefit_text": "In a large school trial, three-year myopia incidence was about thirty percent with added outdoor time versus about forty percent without — roughly a quarter fewer new cases — figures UNVERIFIED in this edition (ported from a He et al. randomized trial; not verified against the study).", "sources": "Canadian 24-Hour Movement Guidelines for Children and Youth (cited for the recommended activity pattern, not the trial figures). https://csepguidelines.ca/guidelines/children-youth/", "notes": "UNVERIFIED — figures ported from a peer-reviewed randomized trial (He et al.) without a verified citation; the cited guidelines page states none of them. See docs/verification/spot-read.md.", "urls": ["https://csepguidelines.ca/guidelines/children-youth/"]}, {"id": "30-003", "chapter_num": 30, "chapter_title": "School-age children", "chapter_file": "30-school-age-children.md", "number": 3, "title": "Brace scoliosis early instead of watching it worsen", "money": "low", "time": "mid", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "C", "grade": "C", "disputed": false, "cost": "Low money with provincial coverage for the brace; months of wearing it.", "plain": "A curve caught early can be braced; a curve left alone can need surgery. Ask for referral at the first sign of uneven shoulders and back.", "benefit_text": "Bracing succeeded in about seventy-five percent of cases versus about forty-two percent with watchful waiting — figures UNVERIFIED in this edition (ported from a Weinstein trial; not verified against the study).", "sources": "What OHIP covers (cited for specialist-referral coverage, not the bracing figures). https://www.ontario.ca/page/what-ohip-covers", "notes": "UNVERIFIED — figures ported from a peer-reviewed trial (Weinstein) without a verified citation; the cited OHIP page states none of them. Specialist referral is covered under provincial health insurance; confirm brace coverage with the provider. See docs/verification/spot-read.md.", "urls": ["https://www.ontario.ca/page/what-ohip-covers"]}, {"id": "30-004", "chapter_num": 30, "chapter_title": "School-age children", "chapter_file": "30-school-age-children.md", "number": 4, "title": "Ask for depression screening from age twelve", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; a questionnaire at a regular checkup.", "plain": "Teen depression hides behind bad moods and closed doors. A short screening at the family doctor catches what parents miss — and help works best early.", "benefit_text": "Screening adolescents twelve to eighteen for major depression is recommended; early treatment lowers suicide risk. In crisis, call and text 988 any time.", "sources": "https://www.canada.ca/en/public-health/news/2023/11/9-8-8-suicide-crisis-helpline.html", "notes": "Evidence note: screening recommendation ported from the US Preventive Services Task Force; 988 is Canada's national crisis line (English and French only).", "urls": ["https://www.canada.ca/en/public-health/news/2023/11/9-8-8-suicide-crisis-helpline.html"]}, {"id": "30-005", "chapter_num": 30, "chapter_title": "School-age children", "chapter_file": "30-school-age-children.md", "number": 5, "title": "Take bullying seriously — schools must have a plan", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; documenting incidents and writing to the school.", "plain": "Bullying is linked with self-harm and suicidal thinking, not just bad days. Ontario requires every school board to run a bullying prevention and intervention plan — ask for it by name.", "benefit_text": "Bullied children face more than double the risk of suicidal thinking; a school with an enforced plan is safer than silence.", "sources": "https://etfohealthandsafety.ca/site/wp-content/uploads/2019/11/2018-PPM-145-Progressive-Discipline.pdf https://cdnsm5-ss13.sharpschool.com/UserFiles/Servers/Server_14449870/File/Safe%20Schools/144.pdf", "notes": "UNVERIFIED — the PPM 144/145 requirements rest on ministry documents hosted by third parties, not the Ministry of Education site; confirm current policy on ontario.ca. See docs/verification/30-school-age-children.md. Evidence note: risk figures ported from a peer-reviewed meta-analysis (van Geel).", "urls": ["https://cdnsm5-ss13.sharpschool.com/UserFiles/Servers/Server_14449870/File/Safe%20Schools/144.pdf", "https://etfohealthandsafety.ca/site/wp-content/uploads/2019/11/2018-PPM-145-Progressive-Discipline.pdf"]}, {"id": "30-006", "chapter_num": 30, "chapter_title": "School-age children", "chapter_file": "30-school-age-children.md", "number": 6, "title": "Treat high myopia as a blinding disease, not just strong glasses", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; taking follow-up appointments seriously.", "plain": "Very nearsighted eyes stretch and thin, raising the risk of retinal detachment and glaucoma for life. Keep every eye appointment and report flashes and new floaters at once.", "benefit_text": "High myopia greatly raises lifetime risk of retinal detachment, glaucoma, and myopic maculopathy — complications that regular follow-up catches early.", "sources": "https://www.ontario.ca/page/what-ohip-covers", "notes": "Evidence note: complication risks ported from a peer-reviewed review (Haarman). OHIP covers annual eye exams under age twenty (see item 8).", "urls": ["https://www.ontario.ca/page/what-ohip-covers"]}, {"id": "30-007", "chapter_num": 30, "chapter_title": "School-age children", "chapter_file": "30-school-age-children.md", "number": 7, "title": "Know that conversion therapy is a crime in Canada", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; believing your child.", "plain": "Any practice claiming to change a young person's sexual orientation and gender identity is illegal nationwide. A teen who comes out needs safety at home first.", "benefit_text": "Sections 320.101 to 320.104 of the Criminal Code ban conversion therapy; LGBTQ youth facing rejection carry sharply higher suicide risk, and family acceptance protects them.", "sources": "https://laws-lois.justice.gc.ca/eng/acts/c-46/section-320.101.html", "notes": "", "urls": ["https://laws-lois.justice.gc.ca/eng/acts/c-46/section-320.101.html"]}, {"id": "30-008", "chapter_num": 30, "chapter_title": "School-age children", "chapter_file": "30-school-age-children.md", "number": 8, "title": "Use the covered annual eye exam before age twenty", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; the exam is covered.", "plain": "Ontario covers a full eye exam every year for anyone under twenty. Book it yearly — vision changes in school-age children move fast.", "benefit_text": "One major eye exam every twelve months is covered under OHIP for ages nineteen and under; seniors sixty-five and up are covered every eighteen months.", "sources": "https://www.ontario.ca/page/what-ohip-covers", "notes": "Schedule as stated on the official OHIP coverage page; confirm with the optometrist. Quebec: check RAMQ for the equivalent schedule.", "urls": ["https://www.ontario.ca/page/what-ohip-covers"]}, {"id": "30-009", "chapter_num": 30, "chapter_title": "School-age children", "chapter_file": "30-school-age-children.md", "number": 9, "title": "Seal molars and use free dental where eligible", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money for eligible families; one dental visit.", "plain": "Sealants on new molars block most cavities before they start. Ontario's Healthy Smiles program covers free dental for eligible children seventeen and under — check eligibility instead of skipping the dentist.", "benefit_text": "Sealants cut molar cavities sharply in trials; Healthy Smiles Ontario covers eligible children and youth seventeen and under at no cost.", "sources": "http://www.ontario.ca/page/services-covered-by-healthy-smiles-ontario", "notes": "Evidence note: sealant effect ported from a Cochrane review. Healthy Smiles details are from the official Ontario page.", "urls": ["http://www.ontario.ca/page/services-covered-by-healthy-smiles-ontario"]}, {"id": "30-010", "chapter_num": 30, "chapter_title": "School-age children", "chapter_file": "30-school-age-children.md", "number": 10, "title": "Ignore products that claim to cure myopia", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; the money you do not spend.", "plain": "Eye drops, devices, and courses promising to reverse nearsightedness sell hope, not results. No product has been shown to cure myopia.", "benefit_text": "Avoiding unproven products saves the purchase price and the months lost chasing them; false health claims can be reported to the Competition Bureau.", "sources": "https://competition-bureau.canada.ca/en/deceptive-marketing-practices-digest-volume-5", "notes": "The Bureau acts on false and unsubstantiated health-product claims, with penalties up to $750,000 for individuals and $10 million for corporations.", "urls": ["https://competition-bureau.canada.ca/en/deceptive-marketing-practices-digest-volume-5"]}, {"id": "30-011", "chapter_num": 30, "chapter_title": "School-age children", "chapter_file": "30-school-age-children.md", "number": 11, "title": "Cap recreational screen time by age", "money": "0", "time": "low", "willpower": "some", "benefit": "mid", "dimension": "time", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; the effort to hold the line.", "plain": "Set the limit before the device arrives: none under age two, under an hour from two to four, and two hours max for older children and teens — recreational use, not homework.", "benefit_text": "Canadian paediatric guidance: no screen time under two; under one hour daily at two to four; max two hours daily recreational at five to seventeen.", "sources": "https://www.aboutkidshealth.ca/fr/temps-decran-presentation-generale?language=en", "notes": "Guidance via SickKids' AboutKidsHealth, reflecting Canadian Paediatric Society positions.", "urls": ["https://www.aboutkidshealth.ca/fr/temps-decran-presentation-generale?language=en"]}, {"id": "30-012", "chapter_num": 30, "chapter_title": "School-age children", "chapter_file": "30-school-age-children.md", "number": 12, "title": "Follow the 24-Hour Movement Guidelines as a family", "money": "0", "time": "mid", "willpower": "some", "benefit": "low", "dimension": "time", "evidence": "A", "grade": "A", "disputed": false, "cost": "No money; reshaping the daily routine.", "plain": "Move more, sit less, sleep enough — the national guidelines bundle activity, screen limits, and sleep into one daily recipe for ages five to seventeen.", "benefit_text": "At least sixty minutes of moderate-to-vigorous activity daily; nine to eleven hours of sleep at five to thirteen, eight to ten at fourteen to seventeen; two hours max recreational screen time.", "sources": "https://csepguidelines.ca/guidelines/children-youth/", "notes": "", "urls": ["https://csepguidelines.ca/guidelines/children-youth/"]}, {"id": "30-013", "chapter_num": 30, "chapter_title": "School-age children", "chapter_file": "30-school-age-children.md", "number": 13, "title": "Set gaming limits yourself — Canada sets none", "money": "0", "time": "low", "willpower": "some", "benefit": "low", "dimension": "time", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; house rules and consistency.", "plain": "Unlike some countries, Canada has no legal gaming curfew for minors. The limit is yours to set — agree it with your child before the new game lands.", "benefit_text": "Problematic gaming tracks with depression and anxiety in teens; a clear household rule beats nightly negotiation.", "sources": "https://www.aboutkidshealth.ca/fr/temps-decran-presentation-generale?language=en", "notes": "UNVERIFIED — the \"no federal gaming time limits\" claim is verified by absence of such a law; the problem-gaming link is ported from research (Stevens). See docs/verification/30-school-age-children.md.", "urls": ["https://www.aboutkidshealth.ca/fr/temps-decran-presentation-generale?language=en"]}, {"id": "30-014", "chapter_num": 30, "chapter_title": "School-age children", "chapter_file": "30-school-age-children.md", "number": 14, "title": "For long school absences, ask about home instruction", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "time", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; a doctor's note and a written request to the principal.", "plain": "When illness keeps a child home for weeks, Ontario principals can arrange instruction at home with medical evidence and supervisory approval. Ask early — it is not offered automatically.", "benefit_text": "Home instruction under Regulation 298 keeps a sick child from falling a term behind.", "sources": "https://ontario.ca/laws/regulation/900298/v9", "notes": "", "urls": ["https://ontario.ca/laws/regulation/900298/v9"]}, {"id": "30-015", "chapter_num": 30, "chapter_title": "School-age children", "chapter_file": "30-school-age-children.md", "number": 15, "title": "Ask for cycloplegic refraction at the eye exam", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "time", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; one extra step during the covered exam.", "plain": "Drops that relax the focusing muscle let the optometrist measure the true prescription — especially in children, where the eyes work overtime to compensate.", "benefit_text": "Cycloplegic refraction gives the accurate baseline that myopia control depends on.", "sources": "https://www.ontario.ca/page/what-ohip-covers", "notes": "Evidence note: clinical practice ported from the source guide. Ask for it during the covered annual exam (item 8).", "urls": ["https://www.ontario.ca/page/what-ohip-covers"]}, {"id": "31-001", "chapter_num": 31, "chapter_title": "Paths after 18", "chapter_file": "31-paths-after-18.md", "number": 1, "title": "University and college, priced after aid", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "money", "evidence": "C", "grade": "C", "disputed": false, "cost": "No money to apply for aid. Applications run through your province's plan.", "plain": "Do not price school at sticker price. For 2026-27, federal grants reach $4,200 a year and federal loans reach $300 a week with zero federal interest, before provincial top-ups. Colleges run shorter diplomas aimed at local hiring; universities run degrees. Compare net cost after aid, not before.", "benefit_text": "Canada Student Financial Assistance, 2026–27 (2026): full-time grants $4,200/year; loans $300/week; 0% federal interest — figures UNVERIFIED in this edition (not confirmed on the cited page; see docs/verification/spot-read.md). Details in the skills chapter's student-aid item. Four years of grants alone are $16,800 (2026 dollars).", "sources": "https://www.canada.ca/en/employment-social-development/news/2026/03/government-of-canada-extends-financial-supports-for-post-secondary-students.html", "notes": "Benefit graded high: the earnings gap of a degree compounds past $50,000 over a working life; see the 9%-a-year yardstick in the skills chapter.", "urls": ["https://www.canada.ca/en/employment-social-development/news/2026/03/government-of-canada-extends-financial-supports-for-post-secondary-students.html"]}, {"id": "31-002", "chapter_num": 31, "chapter_title": "Paths after 18", "chapter_file": "31-paths-after-18.md", "number": 2, "title": "Apprenticeship: paid to learn, with a ticket that travels", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money to start looking. The catch is finding an employer to sponsor your hours.", "plain": "Apprenticeship pays you while you learn: paid work plus classroom blocks, ending in a journeyperson ticket. The Red Seal endorsement carries that ticket across provinces. Without a sponsor employer, the hours never start — so shop for sponsors, not just schools.", "benefit_text": "Canada (2026): Interprovincial Standards Red Seal Program, a federal–provincial–territorial partnership for designated trades. Apprenticeship combines paid on-the-job hours with technical training; ratios and classroom weeks vary by province and trade — UNVERIFIED at write time. A ticketed trade premium compounds past $50,000 over a working life.", "sources": "https://www.canada.ca/en/employment-social-development/news/2026/03/workforce-training-in-quebec-governments-of-canada-and-quebec-announce-funding-for-sustainable-jobs.html", "notes": "Benefit graded high: the lifetime wage premium of a ticketed trade clears $50,000.", "urls": ["https://www.canada.ca/en/employment-social-development/news/2026/03/workforce-training-in-quebec-governments-of-canada-and-quebec-announce-funding-for-sustainable-jobs.html"]}, {"id": "31-003", "chapter_num": 31, "chapter_title": "Paths after 18", "chapter_file": "31-paths-after-18.md", "number": 3, "title": "The threshold map: match your gates first", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "time", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money. Ten minutes matching your age and status to the paths below.", "plain": "Every path below has hard entry gates: age, status, education. University and college take secondary-school graduates and mature students. Apprenticeship takes workers 16 and up with an employer sponsor. The military takes citizens and permanent residents 17 and up. Federal public-service jobs take adults eligible to work in Canada. Working-holiday programs take citizens 18 to 35, with the range varying by country.", "benefit_text": "Canada (2026): university/college admission from secondary school or as a mature student (usually 19+, varies); apprenticeship from 16 with a sponsor; Canadian Armed Forces from 17 (citizen or permanent resident, parental consent under 18); federal public service 18+ with legal work status; International Experience Canada 18–35 by destination country (exact country ranges UNVERIFIED at write time).", "sources": "https://www.canada.ca/en/department-national-defence/corporate/policies-standards/defence-administrative-orders-directives/5000-series/5002/5002-1-enrolment.html ; https://ircc.canada.ca/iec", "notes": "Mature-student age floors vary by institution — UNVERIFIED at write time. Benefit graded mid for time: ten minutes that prevents months aimed at a closed door.", "urls": ["https://ircc.canada.ca/iec", "https://www.canada.ca/en/department-national-defence/corporate/policies-standards/defence-administrative-orders-directives/5000-series/5002/5002-1-enrolment.html"]}, {"id": "31-004", "chapter_num": 31, "chapter_title": "Paths after 18", "chapter_file": "31-paths-after-18.md", "number": 4, "title": "The military: voluntary service, no conscription", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money to apply. The real price is years of service if you sign.", "plain": "Canada has no conscription; military service is voluntary. The Canadian Armed Forces enroll citizens and permanent residents from age 17, with parental consent under 18. Entry runs through the recruiting system with medical, aptitude, and reliability screening.", "benefit_text": "CAF enrolment (2026, DAOD 5002-1): citizen or permanent resident; minimum age 17 (16 for military-college and civilian-university officer tracks); parental consent required under 18. No peacetime draft exists in Canada.", "sources": "https://www.canada.ca/en/department-national-defence/corporate/policies-standards/defence-administrative-orders-directives/5000-series/5002/5002-1-enrolment.html", "notes": "Pay, benefits, and release supports exist but were not verified against primary pages at write time — left out rather than guessed. Benefit graded mid: steady pay plus training, inside $5,000–$50,000 a year in value.", "urls": ["https://www.canada.ca/en/department-national-defence/corporate/policies-standards/defence-administrative-orders-directives/5000-series/5002/5002-1-enrolment.html"]}, {"id": "31-005", "chapter_num": 31, "chapter_title": "Paths after 18", "chapter_file": "31-paths-after-18.md", "number": 5, "title": "Federal public service: the GC Jobs portal", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money to apply. Applications run through the GC Jobs portal.", "plain": "Federal government jobs are posted centrally and hired on merit through open competitions. Eligibility to work in Canada is the base requirement; most postings ask for English and French in some combination. Student and graduate streams hire with less experience.", "benefit_text": "Canada (2026): GC Jobs is the federal government's central hiring portal; the how-to-apply guide covers profiles, screening, and assessments. Bilingual (English/French) requirements vary by position — exact current student streams UNVERIFIED at write time.", "sources": "https://www.canada.ca/en/public-service-commission/jobs/services/gc-jobs/applying-government-canada-jobs-how-to-apply.html", "notes": "Provinces and municipalities hire separately through their own portals. Benefit graded mid: a public-service salary premium and pension compound past $5,000 quickly.", "urls": ["https://www.canada.ca/en/public-service-commission/jobs/services/gc-jobs/applying-government-canada-jobs-how-to-apply.html"]}, {"id": "31-006", "chapter_num": 31, "chapter_title": "Paths after 18", "chapter_file": "31-paths-after-18.md", "number": 6, "title": "Police, fire, paramedic: each service sets its own gates", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "C", "grade": "C", "disputed": false, "cost": "No money to check requirements. Each service publishes its own gates.", "plain": "Policing, firefighting, and paramedicine hire through their own services with published minimums, usually 18 and up, plus fitness, medical, and background screening. The RCMP hires nationally; the SQ covers Quebec; municipalities run their own police and fire services. Requirements change by service and year, so verify against the current posting.", "benefit_text": "Canada (2026): the RCMP recruits through federal channels including GC Jobs; the SQ and municipal police and fire services recruit through their own portals — exact current age, education, and fitness minimums UNVERIFIED at write time. Typical floor: 18+.", "sources": "https://www.canada.ca/en/public-service-commission/jobs/services/gc-jobs/applying-government-canada-jobs-how-to-apply.html", "notes": "Benefit graded mid: uniformed-service pay and pensions compound past $5,000 quickly.", "urls": ["https://www.canada.ca/en/public-service-commission/jobs/services/gc-jobs/applying-government-canada-jobs-how-to-apply.html"]}, {"id": "31-007", "chapter_num": 31, "chapter_title": "Paths after 18", "chapter_file": "31-paths-after-18.md", "number": 7, "title": "International Experience Canada: work abroad on a Canadian passport", "money": "low", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Application fees and proof of funds apply. The real cost is months abroad on entry-level pay.", "plain": "International Experience Canada lets Canadians aged 18 to 35 work and travel in over 35 partner countries, up to two years depending on the destination. The Working Holiday stream needs no job offer; the Young Professionals and Co-op streams do. Quotas and exact age ranges differ by country.", "benefit_text": "IEC (2026, ircc.canada.ca): Canadian citizens 18–35; 35+ partner countries and territories; stays up to 2 years by destination. Exact per-country age ranges, quotas, and fees are UNVERIFIED at write time.", "sources": "https://ircc.canada.ca/iec ; https://www.canada.ca/en/immigration-refugees-citizenship/services/canadians/international-experience-canada/work-travel-ireland.html", "notes": "Do not confuse IEC with \"pay for a job abroad\" schemes: IEC needs no agent and no job offer for the Working Holiday stream. Benefit graded mid: a year abroad costs and pays inside $5,000–$50,000.", "urls": ["https://ircc.canada.ca/iec", "https://www.canada.ca/en/immigration-refugees-citizenship/services/canadians/international-experience-canada/work-travel-ireland.html"]}, {"id": "31-008", "chapter_num": 31, "chapter_title": "Paths after 18", "chapter_file": "31-paths-after-18.md", "number": 8, "title": "Missing the school path at 18 does not close it", "money": "low", "time": "high", "willpower": "yes", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Upgrading courses cost modest tuition. The real price is months of study alongside work.", "plain": "Missing the school path at 18 does not close it. Colleges and universities admit mature students, usually 19 and up, through upgrading and prior-learning assessment. High-school equivalency runs through adult and continuing education. The exact age floor and upgrading routes differ by institution.", "benefit_text": "Canada (2026): mature-student admission (commonly 19+, varies by institution), academic upgrading, and prior learning assessment and recognition (PLAR) are the standard second-chance routes for learners past 18. The Canada Training Credit ($250/year to a $5,000 lifetime limit, ages 26–65) offsets training fees. Exact age floors, upgrading program names, and PLAR fees are UNVERIFIED at write time.", "sources": "https://www.canada.ca/en/revenue-agency/services/tax/individuals/topics/about-your-tax-return/tax-return/completing-a-tax-return/deductions-credits-expenses/line-45350-canada-training-credit.html", "notes": "Benefit graded mid: a completed credential via upgrading still moves earnings inside $5,000–$50,000 over the years after.", "urls": ["https://www.canada.ca/en/revenue-agency/services/tax/individuals/topics/about-your-tax-return/tax-return/completing-a-tax-return/deductions-credits-expenses/line-45350-canada-training-credit.html"]}, {"id": "32-001", "chapter_num": 32, "chapter_title": "Studying in Canada", "chapter_file": "32-studying-in-canada.md", "number": 1, "title": "Protect your post-graduation work permit from day one", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; the discipline to stay eligible every term.", "plain": "The work permit after graduation is a once-in-a-lifetime document. It depends on full-time study at an eligible school, within the allowed work hours, from the very first term — mistakes in year one can cost it.", "benefit_text": "A post-graduation work permit of up to three years opens the main path from study to work in Canada; losing eligibility closes it. (The \"up to three years\" maximum is UNVERIFIED in this edition — the cited IRCC help page does not state it; confirm validity rules on the IRCC site. See docs/verification/spot-read.md.)", "sources": "https://ircc.canada.ca/english/helpcentre/answer.asp?qnum=511&top=15", "notes": "UNVERIFIED — details such as the 180-day application window and the once-in-a-lifetime rule are from secondary immigration sources; confirm every condition on the IRCC site. See docs/verification/32-studying-in-canada.md.", "urls": ["https://ircc.canada.ca/english/helpcentre/answer.asp?qnum=511&top=15"]}, {"id": "32-002", "chapter_num": 32, "chapter_title": "Studying in Canada", "chapter_file": "32-studying-in-canada.md", "number": 2, "title": "Confirm the school is on the DLI list before paying tuition", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; ten minutes on the IRCC list.", "plain": "Only designated learning institutions can host international students. A school off the list cannot get you a study permit — check before any deposit leaves your account.", "benefit_text": "One check protects a full year of international tuition paid to a school that cannot support your permit.", "sources": "https://www.canada.ca/en/immigration-refugees-citizenship/services/study-canada/study-permit/prepare/designated-learning-institutions-list.html", "notes": "", "urls": ["https://www.canada.ca/en/immigration-refugees-citizenship/services/study-canada/study-permit/prepare/designated-learning-institutions-list.html"]}, {"id": "32-003", "chapter_num": 32, "chapter_title": "Studying in Canada", "chapter_file": "32-studying-in-canada.md", "number": 3, "title": "Get the study permit with proof of funds in hand", "money": "low", "time": "mid", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "A", "grade": "A", "disputed": false, "cost": "The permit fee plus showing the required funds; weeks of processing time.", "plain": "Apply early, with the full financial proof IRCC asks for — tuition plus living costs for the year. Thin paperwork is the classic refusal reason.", "benefit_text": "Single applicants needed $23,448 in proof of funds from September 1, 2026; confirm the current figure on the IRCC page before applying.", "sources": "https://www.canada.ca/en/immigration-refugees-citizenship/services/study-canada/study-permit/get-documents/financial-support.html", "notes": "UNVERIFIED — the $23,448 figure is from secondary sources; the IRCC page lagged at write time. Confirm the current amount on the IRCC page before applying. See docs/verification/32-studying-in-canada.md.", "urls": ["https://www.canada.ca/en/immigration-refugees-citizenship/services/study-canada/study-permit/get-documents/financial-support.html"]}, {"id": "32-004", "chapter_num": 32, "chapter_title": "Studying in Canada", "chapter_file": "32-studying-in-canada.md", "number": 4, "title": "Quebec-bound: get the CAQ before the study permit", "money": "low", "time": "mid", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "The CAQ fee plus a separate application to Quebec before IRCC.", "plain": "Quebec runs its own pre-approval for study programs longer than six months. No CAQ means no study permit — start with Quebec, then go federal.", "benefit_text": "The Certificat d'acceptation du Québec is mandatory for most Quebec study programs over six months; applying late delays everything downstream.", "sources": "https://www.canadim.com/study/become-an-international-student/caq-quebec/amp/", "notes": "UNVERIFIED — the CAQ requirement and fee are from secondary immigration sources; confirm on the MIFI site. See docs/verification/32-studying-in-canada.md.", "urls": ["https://www.canadim.com/study/become-an-international-student/caq-quebec/amp/"]}, {"id": "32-005", "chapter_num": 32, "chapter_title": "Studying in Canada", "chapter_file": "32-studying-in-canada.md", "number": 5, "title": "Budget tuition on top of living costs, not instead of them", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; an honest spreadsheet.", "plain": "Proof-of-funds covers living costs; tuition is a separate pile. Families that budget one pot for both run dry mid-year.", "benefit_text": "Separating the two piles keeps a mid-year shortfall from forcing unauthorized work and permit trouble.", "sources": "https://www.canada.ca/en/immigration-refugees-citizenship/services/study-canada/study-permit/get-documents/financial-support.html", "notes": "", "urls": ["https://www.canada.ca/en/immigration-refugees-citizenship/services/study-canada/study-permit/get-documents/financial-support.html"]}, {"id": "32-006", "chapter_num": 32, "chapter_title": "Studying in Canada", "chapter_file": "32-studying-in-canada.md", "number": 6, "title": "Lock in health insurance before you land", "money": "low", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "The annual premium for the school or provincial plan.", "plain": "International students are not automatically covered on arrival. Ontario routes most through school plans; Quebec has its own waiting rules — confirm what covers you from day one and buy the gap.", "benefit_text": "A single uninsured hospital visit can cost more than years of premiums; school-mandated plans exist precisely for this.", "sources": "https://www.cicnews.com/2026/08/ontario-international-students-face-20-fee-hike-for-compulsory-health-insurance-0879525.html", "notes": "UNVERIFIED — UHIP pricing and provincial waiting rules are from secondary sources; confirm with the school's international office. See docs/verification/32-studying-in-canada.md.", "urls": ["https://www.cicnews.com/2026/08/ontario-international-students-face-20-fee-hike-for-compulsory-health-insurance-0879525.html"]}, {"id": "32-007", "chapter_num": 32, "chapter_title": "Studying in Canada", "chapter_file": "32-studying-in-canada.md", "number": 7, "title": "Stay full-time — it is the root of your work rights", "money": "0", "time": "low", "willpower": "some", "benefit": "mid", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; the course load and the grades to keep it.", "plain": "Off-campus work rights and the future work permit both grow out of full-time enrolment. Dropping to part-time without authorization can cancel both.", "benefit_text": "Full-time status at an eligible institution is the foundation IRCC checks for work authorization and the post-graduation permit.", "sources": "https://ircc.canada.ca/english/helpcentre/answer.asp?qnum=511&top=15", "notes": "", "urls": ["https://ircc.canada.ca/english/helpcentre/answer.asp?qnum=511&top=15"]}, {"id": "32-008", "chapter_num": 32, "chapter_title": "Studying in Canada", "chapter_file": "32-studying-in-canada.md", "number": 8, "title": "Respect the twenty-four-hour weekly work cap — all jobs combined", "money": "0", "time": "low", "willpower": "some", "benefit": "mid", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; turning down extra shifts.", "plain": "The cap counts every job together, not per employer. Two part-time jobs at fifteen hours each already break it.", "benefit_text": "IRCC allows up to twenty-four hours per week off campus during regular terms; exceeding it is unauthorized work and can endanger the permit.", "sources": "https://www.canada.ca/en/immigration-refugees-citizenship/services/study-canada/work/work-off-campus.html", "notes": "", "urls": ["https://www.canada.ca/en/immigration-refugees-citizenship/services/study-canada/work/work-off-campus.html"]}, {"id": "32-009", "chapter_num": 32, "chapter_title": "Studying in Canada", "chapter_file": "32-studying-in-canada.md", "number": 9, "title": "Do not work before classes start", "money": "0", "time": "low", "willpower": "some", "benefit": "mid", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "No money; waiting for the term to begin.", "plain": "Work authorization starts with the study program, not with the plane ticket. A job in the arrival weeks is unauthorized work.", "benefit_text": "Starting work only after the program begins keeps the study-permit conditions clean from day one.", "sources": "https://www.canada.ca/en/immigration-refugees-citizenship/services/study-canada/work/work-off-campus.html", "notes": "", "urls": ["https://www.canada.ca/en/immigration-refugees-citizenship/services/study-canada/work/work-off-campus.html"]}, {"id": "32-010", "chapter_num": 32, "chapter_title": "Studying in Canada", "chapter_file": "32-studying-in-canada.md", "number": 10, "title": "Keep a paper trail of everything", "money": "0", "time": "low", "willpower": "no", "benefit": "low", "dimension": "time", "evidence": "C", "grade": "C", "disputed": false, "cost": "No money; a folder, physical and digital.", "plain": "Permits, enrolment letters, transcripts, pay stubs, leases — keep them all. Extensions, permits, and disputes are decided on documents, not memory.", "benefit_text": "A complete file turns permit renewals and any dispute into paperwork instead of a crisis.", "sources": "https://www.canada.ca/en/immigration-refugees-citizenship/services/study-canada/study-permit/prepare/designated-learning-institutions-list.html", "notes": "", "urls": ["https://www.canada.ca/en/immigration-refugees-citizenship/services/study-canada/study-permit/prepare/designated-learning-institutions-list.html"]}, {"id": "33-001", "chapter_num": 33, "chapter_title": "Living with a disability", "chapter_file": "33-living-with-disability.md", "number": 1, "title": "Learn the signs of autonomic dysreflexia if you have a spinal cord injury", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free to learn. It costs teaching everyone around you too.", "plain": "For injuries at the mid-back and higher, triggers like a full bladder, tight clothing, and pressure sores can set off a dangerous spike in blood pressure: pounding headache, sweating, flushed skin. Sit upright, loosen everything, remove the trigger, and call 911 — it is an emergency, not a headache.", "benefit_text": "The Christopher Reeve Foundation: autonomic dysreflexia is a potentially life-threatening hypertensive emergency in people with spinal cord injury at T6 and above; first aid is sitting upright, loosening constrictive clothing, identifying and removing the stimulus, and calling emergency services (911 in Canada).", "sources": "https://www.christopherreeve.org/todays-care/living-with-paralysis/health/secondary-conditions/autonomic-dysreflexia/", "notes": "", "urls": ["https://www.christopherreeve.org/todays-care/living-with-paralysis/health/secondary-conditions/autonomic-dysreflexia/"]}, {"id": "33-002", "chapter_num": 33, "chapter_title": "Living with a disability", "chapter_file": "33-living-with-disability.md", "number": 2, "title": "Watch for the dark years after a spinal cord injury — yours or a loved one's", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free. It costs paying attention long after rehab ends.", "plain": "Suicide risk after spinal cord injury runs about five times the general rate, and nine in ten of those deaths happen in the first ten years. The danger window stays open long after rehab ends. Keep the crisis line number where everyone in the house can see it.", "benefit_text": "Savic et al., Spinal Cord 2018: the suicide rate after spinal cord injury was about 5 times the general population rate; 91% of suicides occurred within the first 10 years. Canada's 988 crisis line operates in English and French, 24 hours a day. DOI 10.1038/sc.2017.98.", "sources": "https://doi.org/10.1038/sc.2017.98 and https://988.ca", "notes": "", "urls": ["https://988.ca", "https://doi.org/10.1038/sc.2017.98"]}, {"id": "33-003", "chapter_num": 33, "chapter_title": "Living with a disability", "chapter_file": "33-living-with-disability.md", "number": 3, "title": "Know how involuntary admission works before a crisis", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free to learn. In a crisis, this knowledge is worth more than money.", "plain": "In Ontario, a doctor can hold a person for a psychiatric assessment for up to three days on a Form 1; longer detention needs a second doctor's certificate and a rights notice. Quebec requires a court order with two psychiatric exams. The details differ, but in both provinces the patient gets told their rights and gets a review.", "benefit_text": "Ontario's Mental Health Act: s.15 (Form 1) — a physician's application for psychiatric assessment, up to 72 hours; s.20 (Form 3) — a certificate of involuntary admission by a different physician, with a Form 30 notice of rights, up to 2 weeks, subject to review. Quebec's Loi P-38.001: temporary confinement requires court authorization, normally after two psychiatric examinations within 96 hours.", "sources": "https://www.ontario.ca/laws/statute/90m07 and https://protecteurducitoyen.qc.ca/sites/default/files/pdf/rapports_speciaux/2011-02_P-38_EN.pdf", "notes": "", "urls": ["https://protecteurducitoyen.qc.ca/sites/default/files/pdf/rapports_speciaux/2011-02_P-38_EN.pdf", "https://www.ontario.ca/laws/statute/90m07"]}, {"id": "33-004", "chapter_num": 33, "chapter_title": "Living with a disability", "chapter_file": "33-living-with-disability.md", "number": 4, "title": "Protect the caregiver's health too — strain kills", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free to arrange in principle; respite services may have fees or wait lists.", "plain": "Looking after a disabled spouse around the clock is itself a health risk. Strained elderly caregivers died at higher rates than non-caregivers in a landmark study. Respite care, home support, and your own doctor visits are not luxuries; they keep the caregiver alive to keep caring.", "benefit_text": "Schulz and Beach, JAMA 1999: strained spousal caregivers aged 66–96 had 63% higher mortality over 4 years (RR 1.63) than non-caregiving controls; non-strained caregivers showed no excess risk.", "sources": "https://jamanetwork.com/journals/jama/fullarticle/192209", "notes": "", "urls": ["https://jamanetwork.com/journals/jama/fullarticle/192209"]}, {"id": "33-005", "chapter_num": 33, "chapter_title": "Living with a disability", "chapter_file": "33-living-with-disability.md", "number": 5, "title": "Check skin every day if you sit or lie all day", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free. A mirror, a few minutes, and the discipline to do it daily.", "plain": "Pressure sores start as a red patch that does not fade and can rot down to the bone in days. The prevention is boring and total: shift weight often, keep skin clean and dry, eat enough protein, and inspect every inch daily — use a mirror for the parts you cannot see, a helper for the rest.", "benefit_text": "The UK's NICE guideline on pressure ulcers: assess skin in areas of pressure, encourage at-risk adults to change position frequently and at least every 6 hours (every 4 hours for high-risk adults), and use pressure-redistributing equipment. Daily skin inspection and repositioning are the standard prevention where no drug exists.", "sources": "https://www.nice.org.uk/guidance/cg179/chapter/recommendations", "notes": "", "urls": ["https://www.nice.org.uk/guidance/cg179/chapter/recommendations"]}, {"id": "33-006", "chapter_num": 33, "chapter_title": "Living with a disability", "chapter_file": "33-living-with-disability.md", "number": 6, "title": "Do not buy cures for paralysis, blindness, or deafness from the internet", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "money", "evidence": "C", "grade": "C", "disputed": false, "cost": "Free to refuse. The sellers charge thousands; the refusal saves both money and health.", "plain": "No pill, no stem-cell injection sold online, no device restores a severed spinal cord, dead retinal cells, dead hair cells in the ear. What the sellers take is money and hope; what some take besides is health, through infections and botched procedures.", "benefit_text": "Health Canada: unauthorized cell therapies, including \"autologous stem cell\" treatments sold by for-profit clinics, \"have not been proven to be safe or effective\"; the department has taken enforcement action against clinics offering them. Genuine cell therapies in Canada are available only through authorized clinical trials.", "sources": "https://recalls-rappels.canada.ca/en/alert-recall/health-canada-advising-canadians-about-potential-health-risks-associated-unauthorized", "notes": "", "urls": ["https://recalls-rappels.canada.ca/en/alert-recall/health-canada-advising-canadians-about-potential-health-risks-associated-unauthorized"]}, {"id": "33-007", "chapter_num": 33, "chapter_title": "Living with a disability", "chapter_file": "33-living-with-disability.md", "number": 7, "title": "Claim every disability dollar: get the tax credit first, then the benefits", "money": "0", "time": "mid", "willpower": "some", "benefit": "high", "dimension": "money", "evidence": "C", "grade": "C", "disputed": false, "cost": "Free to apply; the form needs a doctor or nurse practitioner to fill in the medical part.", "plain": "The disability tax credit is the key that unlocks the registered disability savings plan, the Canada Disability Benefit, and the child disability benefit. Get the credit approved first — the medical part is filled in by a doctor, a nurse practitioner — then apply for each benefit on its own; none of them starts automatically.", "benefit_text": "2026 figures: the Disability Tax Credit is a $10,341 non-refundable credit (worth up to about $1,448 in federal tax reduction), claimed with Form T2201 for a severe and prolonged impairment. The RDSP accepts up to $200,000 in lifetime contributions, with up to $70,000 in grants and $20,000 in bonds. The Canada Disability Benefit pays up to $204.20 a month (July 2026–June 2027) to people aged 18–64 who hold the DTC and apply; it is income-tested and must be applied for — it does not start automatically.", "sources": "https://www.canada.ca/en/department-finance/news/2026/05/secretary-of-state-long-highlights-actions-to-make-it-easier-to-access-the-disability-tax-credit.html and https://www.canada.ca/en/revenue-agency/services/tax/registered-plans-administrators/registered-disability-savings-plans-rdsps/deposits.html and https://livingunlimited.ca/canada-disability-benefit-complete-guide/", "notes": "", "urls": ["https://livingunlimited.ca/canada-disability-benefit-complete-guide/", "https://www.canada.ca/en/department-finance/news/2026/05/secretary-of-state-long-highlights-actions-to-make-it-easier-to-access-the-disability-tax-credit.html", "https://www.canada.ca/en/revenue-agency/services/tax/registered-plans-administrators/registered-disability-savings-plans-rdsps/deposits.html"]}, {"id": "33-008", "chapter_num": 33, "chapter_title": "Living with a disability", "chapter_file": "33-living-with-disability.md", "number": 8, "title": "Claim the Home Accessibility Tax Credit for disability renovations", "money": "high", "time": "mid", "willpower": "no", "benefit": "mid", "dimension": "money", "evidence": "C", "grade": "C", "disputed": false, "cost": "The renovation itself costs thousands; the credit refunds part of it at tax time. Keep every receipt.", "plain": "Widening a doorway, adding a ramp, putting grab bars in the bathroom counts as an eligible renovation when someone in the home has a disability; age sixty-five and up also qualifies. Keep every receipt: the credit refunds part of the cost at tax time, up to a yearly expense limit.", "benefit_text": "The federal Home Accessibility Tax Credit covers up to $20,000 of eligible expenses per year (non-refundable); at 2026 rates that is worth up to about $2,800 in federal tax savings.", "sources": "Canada Revenue Agency — Home accessibility expenses (HATC): claim up to $20,000/year in eligible expenses; qualifying individual is 65+ or DTC-eligible. <https://www.canada.ca/en/revenue-agency/services/tax/individuals/topics/about-your-tax-return/tax-return/completing-a-tax-return/deductions-credits-expenses/line-398-home-accessibility-expenses.html>", "notes": "Do the grab bars and the ramp before the fall, not after — most disabling falls happen at home, and these are afternoon jobs that prevent midnight disasters. The $2,800 figure uses the 2026 lowest federal rate of 14% ($20,000 × 14%).", "urls": ["https://www.canada.ca/en/revenue-agency/services/tax/individuals/topics/about-your-tax-return/tax-return/completing-a-tax-return/deductions-credits-expenses/line-398-home-accessibility-expenses.html"]}, {"id": "33-009", "chapter_num": 33, "chapter_title": "Living with a disability", "chapter_file": "33-living-with-disability.md", "number": 9, "title": "Know your guide-dog rights in Ontario", "money": "0", "time": "low", "willpower": "no", "benefit": "mid", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free to know; the dog itself comes through accredited training programs.", "plain": "Ontario law gives blind people the right to bring a guide dog into any place the public can go — restaurants, taxis, shops, apartments. Staff may ask for the dog's identification, but refusing entry because of the dog is illegal, and so is charging extra.", "benefit_text": "Ontario's Blind Persons' Rights Act (R.S.O. 1990, c. B.7), s.2: no person shall deny accommodation, services, or facilities to a blind person accompanied by a guide dog. The Accessibility for Ontarians with Disabilities Act and the Human Rights Code add further protection. (Quebec has its own regime — this item covers Ontario only.)", "sources": "https://www.ontario.ca/laws/statute/90b07", "notes": "", "urls": ["https://www.ontario.ca/laws/statute/90b07"]}, {"id": "33-010", "chapter_num": 33, "chapter_title": "Living with a disability", "chapter_file": "33-living-with-disability.md", "number": 10, "title": "Ask the school for accommodations in writing", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free. It costs the effort to put the request in writing and keep copies.", "plain": "Schools in Ontario must accommodate disability up to the point of undue hardship — extra time, assistive tech, a quieter room. Put the request in writing, name the barrier, and keep copies. If the school stalls, the Human Rights Commission's education policy is the document that backs you.", "benefit_text": "The Ontario Human Rights Commission's Policy on accessible education: education providers have a legal duty to accommodate students with disabilities to the point of undue hardship; accommodation does not mean lowering bona fide academic requirements.", "sources": "http://www3.ohrc.on.ca/en/policy-accessible-education-students-disabilities", "notes": "", "urls": ["http://www3.ohrc.on.ca/en/policy-accessible-education-students-disabilities"]}, {"id": "33-011", "chapter_num": 33, "chapter_title": "Living with a disability", "chapter_file": "33-living-with-disability.md", "number": 11, "title": "After a disabling change, let the doctor and the ministry decide about driving", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free to report. An assessment for adaptive controls may have fees.", "plain": "In Ontario, doctors must report patients whose condition could make driving unsafe, and drivers must report changes in their own fitness to drive. Losing the licence is not automatic: the ministry can approve adaptive controls, from hand controls to left-foot accelerators, after an assessment.", "benefit_text": "O. Reg. 340/94, s.14: a licence holder must not suffer from a disability likely to significantly interfere with safe driving; physicians must report patients 16 and older with conditions that may make driving dangerous. The ministry reviews medical reports and can impose conditions or approve adaptive equipment rather than cancelling the licence outright.", "sources": "https://www.ontario.ca/laws/regulation/940340/v12?search=street+car+cameras and http://www.ontario.ca/document/print/book/80362", "notes": "", "urls": ["http://www.ontario.ca/document/print/book/80362", "https://www.ontario.ca/laws/regulation/940340/v12?search=street+car+cameras"]}, {"id": "33-012", "chapter_num": 33, "chapter_title": "Living with a disability", "chapter_file": "33-living-with-disability.md", "number": 12, "title": "If work can be adjusted, the employer must adjust it — up to undue hardship", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "money", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free to request. It costs the courage to put the request in writing.", "plain": "Ontario employers must accommodate disability to the point of undue hardship, and only three things count as hardship: cost, outside funding, and health and safety. Annoyance, morale, and other people's preferences do not count. The burden of proof sits with the employer, not with you.", "benefit_text": "The Ontario Human Rights Commission: the duty to accommodate requires changes to rules, schedules, or equipment unless they cause undue hardship, judged only on cost, outside sources of funding, and health and safety requirements; inconvenience or third-party preferences are not valid defences. Quebec's Charter of human rights and freedoms, s.10, provides parallel protection.", "sources": "https://www.ohrc.on.ca/en/policy-ableism-and-discrimination-based-disability/9-undue-hardship and https://www.ohrc.on.ca/en/learning/working-together-code-and-aoda/part-3-understanding-duty-accommodate", "notes": "", "urls": ["https://www.ohrc.on.ca/en/learning/working-together-code-and-aoda/part-3-understanding-duty-accommodate", "https://www.ohrc.on.ca/en/policy-ableism-and-discrimination-based-disability/9-undue-hardship"]}, {"id": "33-013", "chapter_num": 33, "chapter_title": "Living with a disability", "chapter_file": "33-living-with-disability.md", "number": 13, "title": "Name your substitute decision-maker while you still can", "money": "low", "time": "low", "willpower": "no", "benefit": "high", "dimension": "freedom", "evidence": "B", "grade": "B", "disputed": false, "cost": "A lawyer or a legal clinic can prepare the documents; some are free from government guides.", "plain": "If you ever become unable to make your own decisions, someone has to decide for you. In Ontario, sign two documents in advance: a continuing power of attorney for property and a power of attorney for personal care. Quebec's equivalent is the protection mandate, which a court must approve before it takes effect. Without one, the public guardian may end up deciding for you.", "benefit_text": "Ontario's Substitute Decisions Act, 1992: a continuing power of attorney for property covers finances; a power of attorney for personal care covers health care, housing, and daily life. Quebec's protection mandate names mandataries for personal care and property and must be homologated (court-approved) to take effect.", "sources": "https://www.ontario.ca/laws/statute/92s30/v13 and https://cdn-contenu.quebec.ca/cdn-contenu/curateur-public/pdf/dep_mandat_en.pdf", "notes": "", "urls": ["https://cdn-contenu.quebec.ca/cdn-contenu/curateur-public/pdf/dep_mandat_en.pdf", "https://www.ontario.ca/laws/statute/92s30/v13"]}, {"id": "33-014", "chapter_num": 33, "chapter_title": "Living with a disability", "chapter_file": "33-living-with-disability.md", "number": 14, "title": "Get hearing aids early if you need them — they may slow mental decline", "money": "high", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Thousands of dollars a pair; partial coverage exists through some provincial programs and veterans' benefits.", "plain": "Hearing loss isolates people, and isolation drags the brain down with it. In a large trial, older adults at high risk of dementia who got hearing aids and counselling declined almost half as slowly as those who waited. The devices help hearing on day one; the brain benefit is the bonus.", "benefit_text": "The ACHIEVE trial (The Lancet, 2023): 977 adults aged 70–84 with untreated hearing loss, followed for 3 years. Hearing aids slowed cognitive decline by 48% over three years in the subgroup at higher dementia risk.", "sources": "https://UMC.EDU/news/News_Articles/2023/07/MIND-Center-ACHIEVE.html", "notes": "", "urls": ["https://UMC.EDU/news/News_Articles/2023/07/MIND-Center-ACHIEVE.html"]}, {"id": "33-015", "chapter_num": 33, "chapter_title": "Living with a disability", "chapter_file": "33-living-with-disability.md", "number": 15, "title": "After a stroke, push for organized stroke-unit rehab", "money": "0", "time": "high", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "C", "grade": "C", "disputed": false, "cost": "Free under provincial insurance. It costs weeks of hard work.", "plain": "Stroke recovery is not one thing but a team: physiotherapy, speech therapy, occupational therapy, and nursing, coordinated in a dedicated unit. Ask for referral to a stroke unit, a coordinated rehab program — recovery is fastest in the first months, and the window does not reopen.", "benefit_text": "The Heart and Stroke Foundation of Canada: rehabilitation can take place in a dedicated stroke rehabilitation unit, a specialized rehab hospital, a community clinic, or at home with home care; starting rehab as soon as you are ready matters because the brain recovers through retraining. Ask for the coordinated program rather than scattered appointments.", "sources": "https://www.heartandstroke.ca/en/stroke/recovery-and-support/stroke-care/stroke-rehabilitation/", "notes": "", "urls": ["https://www.heartandstroke.ca/en/stroke/recovery-and-support/stroke-care/stroke-rehabilitation/"]}, {"id": "33-016", "chapter_num": 33, "chapter_title": "Living with a disability", "chapter_file": "33-living-with-disability.md", "number": 16, "title": "If you face discrimination at work, file where it counts", "money": "0", "time": "mid", "willpower": "yes", "benefit": "high", "dimension": "money", "evidence": "C", "grade": "C", "disputed": false, "cost": "Free to file. It costs time and the courage to put it in writing.", "plain": "Being passed over, fired, harassed because of disability is illegal. In Ontario, complaints go to the Human Rights Tribunal; in Quebec, to the human-rights commission. Write down dates, names, and what was said while it is fresh — memories fade and files do not.", "benefit_text": "Author advice, graded C: Ontario's Human Rights Tribunal and Quebec's Commission des droits de la personne handle disability-discrimination complaints; contemporaneous notes are the backbone of any case. The underlying right — accommodation to the point of undue hardship — is set out in the Ontario Human Rights Commission's guidance.", "sources": "https://www.ohrc.on.ca/en/learning/working-together-code-and-aoda/part-3-understanding-duty-accommodate", "notes": "", "urls": ["https://www.ohrc.on.ca/en/learning/working-together-code-and-aoda/part-3-understanding-duty-accommodate"]}, {"id": "34-001", "chapter_num": 34, "chapter_title": "The home medicine cabinet: don't poison yourself", "chapter_file": "34-home-medicine-cabinet.md", "number": 1, "title": "Count acetaminophen across every product", "money": "0", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "C", "grade": "C", "disputed": false, "cost": "Free. It costs reading every label, every time.", "plain": "Acetaminophen hides in cold remedies, sleep aids, and prescription painkillers under names like APAP and paracetamol. Doubling up by accident is the most common cause of sudden liver failure. Add up the milligrams from every bottle before you swallow.", "benefit_text": "Larson et al., 2005: among 662 US acute-liver-failure cases, 275 (42%) were acetaminophen-related; 27% of those died before transplant; 38% of the unintentional overdoses had taken two or more acetaminophen-containing products. DOI 10.1002/hep.20948 — figures UNVERIFIED in this edition (abstract-level citation; full text not checked; see docs/verification/spot-read.md).", "sources": "https://doi.org/10.1002/hep.20948", "notes": "", "urls": ["https://doi.org/10.1002/hep.20948"]}, {"id": "34-002", "chapter_num": 34, "chapter_title": "The home medicine cabinet: don't poison yourself", "chapter_file": "34-home-medicine-cabinet.md", "number": 2, "title": "Give no aspirin to children and teenagers", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free — it is about not giving, not buying.", "plain": "Aspirin during a viral illness in the young can trigger Reye's syndrome — sudden brain swelling and liver failure. For fever in anyone under eighteen, use acetaminophen; ibuprofen is the other standard option.", "benefit_text": "Reye's syndrome cases fell sharply after warnings linked aspirin to the illness during viral infections in children; US surveillance documented the decline coinciding with reduced aspirin use in children. Health Canada's labelling guide restricts acetylsalicylic acid products from pediatric use.", "sources": "https://www.cdc.gov/mmwr/preview/mmwrhtml/00001906.htm and https://www.canada.ca/content/dam/hc-sc/migration/hc-sc/dhp-mps/alt_formats/pdf/prodpharma/applic-demande/guide-ld/label-etiquet-pharm/asa_gd_aas_ld-eng.pdf", "notes": "", "urls": ["https://www.canada.ca/content/dam/hc-sc/migration/hc-sc/dhp-mps/alt_formats/pdf/prodpharma/applic-demande/guide-ld/label-etiquet-pharm/asa_gd_aas_ld-eng.pdf", "https://www.cdc.gov/mmwr/preview/mmwrhtml/00001906.htm"]}, {"id": "34-003", "chapter_num": 34, "chapter_title": "The home medicine cabinet: don't poison yourself", "chapter_file": "34-home-medicine-cabinet.md", "number": 3, "title": "Respect NSAIDs — they bleed stomachs", "money": "low", "time": "low", "willpower": "some", "benefit": "high", "dimension": "death", "evidence": "A", "grade": "A", "disputed": false, "cost": "The pills are cheap; the discipline to use the lowest dose for the shortest time is the real price.", "plain": "Ibuprofen and naproxen ease pain by blocking the same enzymes that protect the stomach lining. Weeks of daily use can open an ulcer that bleeds without warning. Use the lowest dose for the shortest time, take them with food, and ask about stomach protection if daily use is unavoidable.", "benefit_text": "The Coxib and traditional NSAID Trialists' Collaboration (Lancet 2013), pooling randomized trials: NSAIDs roughly quadrupled the risk of upper gastrointestinal complications versus placebo — ibuprofen RR 3.97, naproxen RR 4.22.", "sources": "http://www.thelancet.com/action/showPdf?pii=S0140-6736%2813%2960900-9", "notes": "", "urls": ["http://www.thelancet.com/action/showPdf?pii=S0140-6736%2813%2960900-9"]}, {"id": "34-004", "chapter_num": 34, "chapter_title": "The home medicine cabinet: don't poison yourself", "chapter_file": "34-home-medicine-cabinet.md", "number": 4, "title": "Give no over-the-counter cough and cold medicine under age six", "money": "0", "time": "low", "willpower": "no", "benefit": "high", "dimension": "death", "evidence": "B", "grade": "B", "disputed": false, "cost": "Free — it is about not giving, not buying.", "plain": "Cough and cold syrups do not work in small children and have landed toddlers in emergency rooms with racing hearts and overdoses. Health Canada says keep them away from children under six entirely — honey and fluids do more, with none of the risk.", "benefit_text": "Health Canada: cough and cold products must not be given to children under 6; they offer little benefit at that age and have caused serious harm, including death from overdose.", "sources": "https://recalls-rappels.canada.ca/en/alert-recall/health-canada-reminds-parents-not-give-cough-and-cold-medication-children-under-6", "notes": "", "urls": ["https://recalls-rappels.canada.ca/en/alert-recall/health-canada-reminds-parents-not-give-cough-and-cold-medication-children-under-6"]}]);
